window.AKT.tanta = [{"id":"birth-house-limonos","name":{"ar":"بيت الميلاد فوق مقهى «ليمونوس» – شارع البحر","en":"Birth house above Café Limonos, Shari' al-Bahr"},"kind":"home","lat":null,"lng":null,"text":{"ar":"وُلد في 10 يونيو 1962 في بيت يعلو مقهى «ليمونوس» الشهير في شارع البحر بطنطا، وكان له فيه جار يوناني أحبه وتعلّق به. وكتب لاحقًا أن مقهى ليمنوس ما زال قائمًا في شارع البحر.","en":"He was born on 10 June 1962 in a house above the well-known Café Limonos on Shari' al-Bahr in Tanta, where he had a Greek neighbour he was fond of. He later wrote that Café Limnos still stands on Shari' al-Bahr."},"year":1962,"source":"https://www.dostor.org/5487332"},{"id":"tharwat-street-home","name":{"ar":"بيته في 9 شارع ثروت (عمارة مبروك الجمل) – حي ثانٍ طنطا","en":"His home at 9 Tharwat Street (Mabrouk al-Gamal building), Tanta District 2"},"kind":"home","lat":null,"lng":null,"text":{"ar":"عاش في شارع ثروت المتفرع من شارع حسن رضوان، وهو شارع جانبي غير مرصوف؛ وروى جيرانه، ومنهم صاحب البقالة المقابلة الحاج إبراهيم، أنه كان يتسوّق منهم بتواضع لأكثر من عشر سنوات.","en":"He lived on Tharwat Street, an unpaved side street off Hassan Radwan Street; neighbours, including the grocer opposite, Hajj Ibrahim, recalled him shopping there modestly for over ten years."},"year":null,"source":"https://www.youm7.com/story/2018/4/4/هنا-عاش-العراب-رحلة-البحث-عن-منزل-أحمد-خالد-توفيق/3729868"},{"id":"lived-here-plaque","name":{"ar":"لافتة «عاش هنا» على منزله","en":"The 'Lived Here' plaque on his home"},"kind":"memorial","lat":null,"lng":null,"text":{"ar":"مساء 30 أبريل 2019 ثبّت الجهاز القومي للتنسيق الحضاري لافتة نحاسية بالعربية والإنجليزية على منزله نصها: «عاش هنا الأديب أحمد خالد توفيق، 9 شارع ثروت، حي ثانٍ، محافظة الغربية، طنطا»، بحضور نجله د. محمد.","en":"On the evening of 30 April 2019 the National Organization for Urban Harmony fixed a bilingual brass plaque to his house reading 'The writer Ahmed Khaled Tawfik lived here, 9 Tharwat Street, District 2, Gharbia, Tanta', with his son Dr Mohamed present."},"year":2019,"source":"https://www.shorouknews.com/news/view.aspx?cdate=30042019&id=b9fc790c-b82d-4ee6-bd6d-3d1fa2481ba1"},{"id":"al-islah-primary-school","name":{"ar":"مدرسة الإصلاح الابتدائية","en":"Al-Islah Primary School"},"kind":"school","lat":null,"lng":null,"text":{"ar":"مدرسته الابتدائية، وكانت قصرًا لأحد أمراء الأسرة المالكة تحوّل إلى مدرسة بعد 1952. كتب عنها «ذكريات مدرسة الإصلاح» (التحرير، 2013)، وذكر لوحة بيكار عند مدخلها التي ساعد مدرّس الرسم في لمساتها الأخيرة.","en":"His primary school, a former royal prince's palace turned into a school after 1952. He wrote about it in 'Memories of Al-Islah School' (Al-Tahrir, 2013), recalling the Bikar painting at its entrance that he helped his art teacher finish."},"year":null,"source":"https://aktowfik.blogspot.com/2013/05/blog-post_13.html"},{"id":"said-el-eryan-prep-school","name":{"ar":"مدرسة سعيد العريان الإعدادية","en":"Said El-Eryan Preparatory School"},"kind":"school","lat":null,"lng":null,"text":{"ar":"قضى فيها المرحلة الإعدادية؛ وكانت مدارسه كلها حكومية، ولم يأخذ دروسًا خصوصية في أي مرحلة.","en":"He attended it for his preparatory years; all his schools were state schools, and he took no private tutoring at any stage."},"year":null,"source":"https://www.dostor.org/5487379"},{"id":"coptic-secondary-school","name":{"ar":"مدرسة الأقباط (الثانوية)","en":"Al-Aqbat (Coptic) School – secondary"},"kind":"school","lat":null,"lng":null,"text":{"ar":"درس المرحلة الثانوية في مدرسة الأقباط الحكومية بطنطا قبل التحاقه بكلية الطب.","en":"He did his secondary schooling at the state-run Al-Aqbat (Coptic) School in Tanta before entering medical school."},"year":null,"source":"https://www.dostor.org/5487379"},{"id":"tanta-faculty-of-medicine","name":{"ar":"كلية الطب – جامعة طنطا، قسم طب المناطق الحارة","en":"Faculty of Medicine, Tanta University – Tropical Medicine Department"},"kind":"university","lat":null,"lng":null,"text":{"ar":"تخرّج فيها عام 1985 ونال منها الدكتوراه في طب المناطق الحارة عام 1997، وظل عضوًا بهيئة تدريسها؛ ويذكره موقع الكلية «أستاذًا ورئيسًا لمجلس قسم طب المناطق الحارة والأمراض المعدية».","en":"He graduated there in 1985, took his doctorate in tropical medicine there in 1997 and stayed on its faculty; the faculty's site lists him as professor and head of the council of the Tropical Medicine and Infectious Diseases department."},"year":1985,"source":"https://med.tanta.edu.eg/depart_tropical_fever/council.aspx"},{"id":"tanta-university-hospital","name":{"ar":"مستشفى طنطا الجامعي","en":"Tanta University Hospital"},"kind":"hospital","lat":null,"lng":null,"text":{"ar":"عمل فيه طبيبَ امتياز عام 1986، ومرّ بعنبر الحروق والحوادث، وكتب عن تلك الأيام في مقاله «امرأتان» (اليوم الجديد، 2016).","en":"He worked there as an intern in 1986, including a rotation in the burns and accident ward, and wrote about it in 'Two Women' (Al-Youm Al-Gedid, 2016)."},"year":1986,"source":"https://aktowfik.blogspot.com/2016/08/blog-post_10.html"},{"id":"al-salam-mosque-murshaha","name":{"ar":"مسجد السلام بالمرشحة","en":"Al-Salam Mosque, Al-Murshaha"},"kind":"mosque","lat":null,"lng":null,"text":{"ar":"صُلّي عليه ظهر الثلاثاء 3 أبريل 2018 في مسجد السلام بمنطقة المرشحة في طنطا، ومنه خرجت جنازته إلى المقابر وسط آلاف من قرائه وزملائه.","en":"His funeral prayer was held at noon on Tuesday 3 April 2018 at Al-Salam Mosque in Tanta's Al-Murshaha area, from where thousands of readers and colleagues walked with him to the cemetery."},"year":2018,"source":"https://www.elwatannews.com/news/details/3238603"},{"id":"qahafa-cemetery-grave","name":{"ar":"قبره في مقابر قحافة","en":"His grave in the Qahafa cemeteries"},"kind":"grave","lat":null,"lng":null,"text":{"ar":"ووري الثرى في مقابر الأسرة بقحافة في طنطا يوم 3 أبريل 2018. يقول مسؤول المقابر إن الزوار يأتون من أنحاء العالم، وإن الشباب زيّنوا القبر بالأشجار والورود، وتعلّق عليه في ذكرى ميلاده رسائل المحبين.","en":"He was buried in the family tomb in the Qahafa cemeteries of Tanta on 3 April 2018. The cemetery keeper says visitors come from all over the world, young readers planted trees and flowers on it, and fans pin letters to it on his birthday."},"year":2018,"source":"https://www.masrawy.com/news/news_regions/details/2018/4/3/1307264/%D8%AC%D8%AB%D9%85%D8%A7%D9%86-%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-%D9%8A%D9%88%D8%A7%D8%B1%D9%89-%D8%A7%D9%84%D8%AB%D8%B1%D9%89-%D9%81%D9%8A-%D9%85%D9%82%D8%A7%D8%A8%D8%B1-%D9%82%D8%AD%D8%A7%D9%81%D8%A9-%D8%A8%D8%B7%D9%86%D8%B7%D8%A7"},{"id":"grave-first-anniversary-2019","name":{"ar":"قرّاؤه عند قبره في الذكرى الأولى","en":"Readers at his grave on the first anniversary"},"kind":"event","lat":null,"lng":null,"text":{"ar":"في 2 أبريل 2019 توافد شباب وفتيات على قبره منذ الصباح، فوضعوا الزهور وقرأوا الفاتحة وعلّقوا أوراقًا عليها مقتطفات من كلماته.","en":"On 2 April 2019 young readers came to his grave from the morning, laying flowers, reciting the Fatiha and pinning up notes with lines from his writing."},"year":2019,"source":"https://www.youm7.com/story/2019/4/2/صور-توافد-الشباب-على-قبر-العراب-أحمد-خالد-توفيق-لإحياء/4193158"},{"id":"tanta-book-fair-2018","name":{"ar":"معرض طنطا للكتاب يحمل اسمه (مدرسة الرافعي)","en":"Tanta Book Fair named after him (El-Rafei School)"},"kind":"event","lat":null,"lng":null,"text":{"ar":"أطلقت الهيئة المصرية العامة للكتاب اسمه على معرض طنطا الصيفي للكتاب في عام رحيله وخصّصت فعاليات لأعماله؛ وأقيم معرض طنطا الثالث بمدرسة الرافعي من 2 إلى 11 أغسطس 2018.","en":"The Egyptian General Book Authority named Tanta's summer book fair after him in the year of his death, with events devoted to his work; the third Tanta Book Fair was held at El-Rafei School from 2 to 11 August 2018."},"year":2018,"source":"https://www.youm7.com/story/2022/6/10/أحمد-خالد-توفيق-أُدرج-بمشروع-عاش-هنا-وأُطلق-اسمه-على/5795757"},{"id":"qaadet-ashab","name":{"ar":"«قعدة أصحاب» – لقاؤه الدوري بالشباب في طنطا","en":"'Qaadet Ashab' – his regular gathering with young people in Tanta"},"kind":"event","lat":null,"lng":null,"text":{"ar":"«قعدة أصحاب» لقاء كان يقيمه في طنطا بصورة دورية، ونُظمت ضمنه مسابقة لرسم قصة مصورة بعنوان «الاتجاه المشاكس» عام 2010. لم يُذكر مكان اللقاء.","en":"'Qaadet Ashab' (Friends' Sitting) was a gathering he held regularly in Tanta; in 2010 it ran a comics contest on the story 'The Contrary Direction'. The venue is not named."},"year":2010,"source":"https://aktowfik.blogspot.com/2010/08/blog-post_9618.html"},{"id":"al-murshaha-canal","name":{"ar":"المرشّحة – «نيل طنطا»","en":"Al-Murshaha – 'Tanta's Nile'"},"kind":"other","lat":null,"lng":null,"text":{"ar":"مصرف المياه الذي يصر أهل طنطا على تسميته «كورنيش»، وكان يفضّل الجلوس عنده على كافيهات الشباب المغلقة؛ ومنه اسم سلسلة مقالاته «ثرثرة فوق المرشّحة» في التحرير (2013).","en":"The drainage canal Tanta's people insist on calling a 'corniche'; he preferred sitting by it to closed-in youth cafés, and named his Al-Tahrir column series 'Chatter on Al-Murshaha' (2013) after it."},"year":2013,"source":"https://aktowfik.blogspot.com/2013/10/blog-post_21.html"},{"id":"sayed-badawi-mosque-moulid","name":{"ar":"مسجد السيد البدوي ومولده","en":"Al-Sayyid al-Badawi Mosque and its moulid"},"kind":"mosque","lat":30.7836,"lng":30.9989,"text":{"ar":"كتب في «إنه أكتوبر» (التحرير، 2015) أن أكتوبر عند «الطنطاوية مثلي» موسم زحف المئات إلى مولد السيد البدوي، وذكر المسجد في مقالات أخرى، منها حديثه عن حريق 2012 الذي كاد يبلغ ما حوله.","en":"In 'It's October' (Al-Tahrir, 2015) he wrote that for Tantawis like him October is the season of crowds arriving for al-Sayyid al-Badawi's moulid; the mosque appears in other columns too, including his account of the 2012 fire that nearly reached its surroundings."},"year":2015,"source":"https://aktowfik.blogspot.com/2015/10/blog-post_15.html"},{"id":"shari-al-bahr-old-tanta","name":{"ar":"شارع البحر وسينما جندولا","en":"Shari' al-Bahr and Cinema Gondola"},"kind":"other","lat":null,"lng":null,"text":{"ar":"في «موضوع محلي جدًا» (التحرير، 2014) رثى طنطا القديمة مع توسعة شارع البحر وقطع أشجاره، وتذكّر سينما جندولا عند تقاطع شارعي الحلو وحسن رضوان التي صارت مقهى، وسينما أوبرا التي صارت قاعة أفراح.","en":"In 'A Very Local Topic' (Al-Tahrir, 2014) he mourned old Tanta as Shari' al-Bahr was widened and its trees cut, recalling Cinema Gondola at the corner of El-Helw and Hassan Radwan streets, now a café, and Cinema Opera, now a wedding hall."},"year":2014,"source":"https://aktowfik.blogspot.com/2014/07/blog-post_30.html"},{"id":"sales-company-fire-2012","name":{"ar":"حريق «شركة بيع المصنوعات»","en":"The fire at the 'Manufactured Goods Sales Company' store"},"kind":"other","lat":null,"lng":null,"text":{"ar":"شاهد من سطح بنايته حريق مبنى «شركة بيع المصنوعات» عام 2012، وكتب أن جزءًا مهمًا من تاريخ طنطا ومن ذكرياته قد احترق، وأن النار كادت تبلغ شارع الخان وسوق ناصر ومسجد السيد البدوي.","en":"He watched the 2012 fire at the 'Manufactured Goods Sales Company' building from his rooftop, writing that an important part of Tanta's history and of his memories had burned, and that it nearly reached Al-Khan Street, Souq Nasser and the Badawi mosque."},"year":2012,"source":"https://aktowfik.blogspot.com/2012/05/blog-post.html"},{"id":"mar-girgis-church-2017","name":{"ar":"كنيسة مار جرجس بطنطا","en":"St George (Mar Girgis) Church, Tanta"},"kind":"other","lat":null,"lng":null,"text":{"ar":"بعد تفجير الكنيسة في أحد الشعانين 9 أبريل 2017 كتب «في أحد الشعانين الدامي» (إضاءات) عن طنطا التي اكتشفت أن كونها بلدة هادئة لا يعفيها من طوفان الدم، متسائلًا كيف دخلت المتفجرات بهذه السهولة.","en":"After the church bombing on Palm Sunday, 9 April 2017, he wrote 'On a Bloody Palm Sunday' (Ida2at) about Tanta learning that being a quiet town did not spare it, asking how the explosives got in so easily."},"year":2017,"source":"https://aktowfik.blogspot.com/2017/04/blog-post_11.html"},{"id":"al-shifa-hospital-fiction","name":{"ar":"«مستشفى الشفاء» – مستشفى طنطاوي باسم زائف","en":"'Al-Shifa Hospital' – a Tanta hospital under a false name"},"kind":"fiction","lat":null,"lng":null,"text":{"ar":"في قصته «خذوها أنتم» (إضاءات، 16 مارس 2018، قبل رحيله بأسابيع) تدور الأحداث في «مستشفى الشفاء» بطنطا؛ قال إن الاسم زائف وإن القصة حقيقية، وبطلها الطبيب عادل الذي يقع عليه عبء كل شيء.","en":"His story 'You Take Her' (Ida2at, 16 March 2018, weeks before his death) is set in 'Al-Shifa Hospital' in Tanta; he says the name is invented but the story true, centred on Dr Adel, who carries the whole place."},"year":2018,"source":"https://aktowfik.blogspot.com/2018/03/blog-post_16.html"}];
